# =========================================================
# DATABASE
# =========================================================

def get_db():
    conn = sqlite3.connect(
        DB_NAME,
        check_same_thread=False
    )
    conn.row_factory = sqlite3.Row
    return conn


def init_database():

    conn = get_db()
    cursor = conn.cursor()

    cursor.execute("""
        CREATE TABLE IF NOT EXISTS users (
            user_id INTEGER PRIMARY KEY,
            username TEXT,
            first_name TEXT,
            joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
    """)

    cursor.execute("""
        CREATE TABLE IF NOT EXISTS voucher_codes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            voucher_id TEXT NOT NULL,
            code TEXT NOT NULL UNIQUE,
            assigned_to INTEGER,
            order_id INTEGER,
            status TEXT DEFAULT 'available'
        )
    """)

    # Permanent history blocks re-adding codes after assignment or stock removal.
    cursor.execute("""
        CREATE TABLE IF NOT EXISTS voucher_code_history (
            code TEXT PRIMARY KEY COLLATE NOCASE,
            voucher_id TEXT NOT NULL,
            added_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
    """)
    cursor.execute("""
        INSERT OR IGNORE INTO voucher_code_history (code, voucher_id)
        SELECT code, voucher_id FROM voucher_codes
    """)

    cursor.execute("""
        CREATE TABLE IF NOT EXISTS bot_settings (
            key TEXT PRIMARY KEY,
            value TEXT
        )
    """)

    cursor.execute("""
        CREATE TABLE IF NOT EXISTS orders (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            voucher_id TEXT NOT NULL,
            quantity INTEGER NOT NULL,
            total INTEGER NOT NULL,
            utr TEXT,
            payer_name TEXT,
            screenshot_file_id TEXT,
            status TEXT DEFAULT 'payment_pending',
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
    """)

    # New human-readable order ID, e.g. HC-20260914-1F0776
    try:
        cursor.execute("ALTER TABLE orders ADD COLUMN order_ref TEXT")
    except sqlite3.OperationalError:
        # Column already exists
        pass

    # Westside new-customer split-payment offer fields.
    migrations = {
        "is_new_user_offer": "INTEGER DEFAULT 0",
        "amount_due": "INTEGER DEFAULT 0",
        "amount_paid": "INTEGER DEFAULT 0",
        "balance_due": "INTEGER DEFAULT 0",
        "payment_stage": "TEXT DEFAULT 'initial'",
        "payment_choice": "TEXT DEFAULT ''",
        "reminder_at": "TEXT",
        "reminder_sent": "INTEGER DEFAULT 0",
    }
    for column, definition in migrations.items():
        try:
            cursor.execute(f"ALTER TABLE orders ADD COLUMN {column} {definition}")
        except sqlite3.OperationalError:
            pass

    # Existing users remain existing users. Only users first recorded after
    # this feature is installed can qualify as new customers.
    cursor.execute("""
        INSERT OR IGNORE INTO bot_settings (key, value)
        VALUES ('westside_offer_start', ?)
    """, (datetime.now().strftime("%Y-%m-%d %H:%M:%S"),))

    cursor.execute("""
        CREATE TABLE IF NOT EXISTS accepted_terms (
            user_id INTEGER PRIMARY KEY,
            terms_version TEXT NOT NULL,
            accepted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
    """)

    cursor.execute("""
        CREATE TABLE IF NOT EXISTS accepted_brand_terms (
            user_id INTEGER NOT NULL,
            voucher_id TEXT NOT NULL,
            terms_version TEXT NOT NULL,
            accepted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            PRIMARY KEY (user_id, voucher_id)
        )
    """)

    conn.commit()
    conn.close()


# =========================================================
# SAVE USER
# =========================================================

def save_user(message):

    user = message.from_user

    conn = get_db()
    cursor = conn.cursor()

    cursor.execute("""
        INSERT OR IGNORE INTO users
        (user_id, username, first_name)
        VALUES (?, ?, ?)
    """, (
        user.id,
        user.username or "",
        user.first_name or ""
    ))
    cursor.execute("""
        UPDATE users
        SET username = ?, first_name = ?
        WHERE user_id = ?
    """, (
        user.username or "",
        user.first_name or "",
        user.id
    ))

    conn.commit()
    conn.close()


