# =========================================================
# FORCE JOIN (CHANNEL ONLY)
# =========================================================

def member_is_joined(chat_id, user_id):
    try:
        member = bot.get_chat_member(chat_id, user_id)

        # Normal channel members/admins/owner
        if member.status in ["member", "administrator", "creator"]:
            return True

        # Restricted members are still joined when Telegram reports is_member=True
        if member.status == "restricted":
            return bool(getattr(member, "is_member", False))

        # left / kicked / unknown = not joined
        return False

    except Exception as e:
        print("Force Join check error:", e)
        return False


def is_joined(user_id):
    # Force Join checks ONLY the configured channel.
    return member_is_joined(CHANNEL, user_id)


