# =========================================================
# HUMAN-READABLE ORDER ID
# =========================================================

def get_order_prefix(voucher_id):
    """Return a short Order ID prefix based on the voucher."""
    # Add more voucher-specific prefixes here as you add vouchers.
    prefixes = {
        "rare_rabbit_250": "RR",
        "femmela_500": "FM",
        "westside_750": "WS",
    }
    if voucher_id in prefixes:
        return prefixes[voucher_id]

    # Safe fallback for any new voucher: first two alphanumeric
    # characters of its voucher ID.
    cleaned = "".join(ch for ch in str(voucher_id).upper() if ch.isalnum())
    return (cleaned[:2] or "VH")


def make_order_ref(order_id, voucher_id=None):
    """Create IDs like BB-20260915-1F0776."""
    prefix = get_order_prefix(voucher_id)
    return f"{prefix}-{datetime.now().strftime('%Y%m%d')}-{int(order_id):06X}"


def get_order_ref(order_id):
    """Return the saved public Order ID for an internal numeric order ID."""
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute(
        "SELECT order_ref, voucher_id FROM orders WHERE id = ?",
        (order_id,)
    )
    row = cursor.fetchone()
    conn.close()

    if row and row["order_ref"]:
        return row["order_ref"]

    # Fallback for old orders created before order_ref was added.
    return make_order_ref(order_id, row["voucher_id"] if row else None)


def get_order(order_id):
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute("SELECT * FROM orders WHERE id = ?", (order_id,))
    order = cursor.fetchone()
    conn.close()
    return order


# =========================================================
# CREATE ORDER
# =========================================================

def create_order(
    user_id,
    voucher_id,
    quantity
):

    voucher = VOUCHERS[voucher_id]
    regular_total = voucher["price"] * quantity

    conn = get_db()
    cursor = conn.cursor()

    cursor.execute("""
        SELECT COUNT(*)
        FROM voucher_codes
        WHERE voucher_id = ?
        AND status = 'available'
    """, (voucher_id,))
    stock = cursor.fetchone()[0]

    if quantity > stock:
        conn.close()
        return None, stock

    is_new_offer = False
    if voucher_id == "westside_750" and quantity == 1:
        cursor.execute("SELECT joined_at FROM users WHERE user_id = ?", (user_id,))
        user_row = cursor.fetchone()
        cursor.execute("SELECT value FROM bot_settings WHERE key = 'westside_offer_start'")
        launch_row = cursor.fetchone()
        if user_row and launch_row and user_row["joined_at"] and user_row["joined_at"] >= launch_row["value"]:
            cursor.execute("SELECT COUNT(*) FROM orders WHERE user_id = ?", (user_id,))
            previous_orders = cursor.fetchone()[0]
            is_new_offer = previous_orders == 0

    total = 170 if is_new_offer else regular_total
    first_payment = 85 if is_new_offer else total
    remaining = 85 if is_new_offer else 0

    cursor.execute("""
        INSERT INTO orders
        (user_id, voucher_id, quantity, total,
         is_new_user_offer, amount_due, amount_paid, balance_due,
         payment_stage, reminder_sent)
        VALUES (?, ?, ?, ?, ?, ?, 0, ?, 'initial', 0)
    """, (
        user_id, voucher_id, quantity, total,
        1 if is_new_offer else 0, first_payment, remaining
    ))

    order_id = cursor.lastrowid
    order_ref = make_order_ref(order_id, voucher_id)
    cursor.execute("UPDATE orders SET order_ref = ? WHERE id = ?", (order_ref, order_id))

    conn.commit()
    conn.close()
    return order_id, stock


# =========================================================
# ORDER SUMMARY
# =========================================================

def show_order_summary(
    chat_id,
    user_id,
    voucher_id,
    quantity
):

    order_id, stock = create_order(
        user_id,
        voucher_id,
        quantity
    )

    if order_id is None:

        bot.send_message(
            chat_id,
            f"❌ Sirf {stock} codes available hain."
        )

        return

    voucher = VOUCHERS[voucher_id]
    order = get_order(order_id)
    total = order["total"]
    is_new_offer = bool(order["is_new_user_offer"])
    first_payment = order["amount_due"]

    keyboard = types.InlineKeyboardMarkup(row_width=1)

    # Everyone sees Pay Now in the order summary.
    # New Westside users get the Full/Half choice only after tapping it.
    keyboard.add(
        types.InlineKeyboardButton(
            "💳 Pay Now",
            callback_data=f"pay_{order_id}"
        )
    )

    keyboard.add(
        types.InlineKeyboardButton(
            "❌ Cancel",
            callback_data=f"cancel_order_{order_id}"
        )
    )

    summary_text = (
        f"🛒 Order Summary\n\n"
        f"🆔 Order ID: {get_order_ref(order_id)}\n"
        f"🎟️ {voucher['name']}\n"
        f"📦 Quantity: {quantity}\n"
        f"💰 Price per code: ₹{voucher['price']}\n"
    )
    if is_new_offer:
        summary_text += (
            "🎉 New Customer Offer: ₹10 OFF\n"
            "💵 Discounted Total: ₹170\n"
            "💳 Pay Now: ₹85\n"
            "🔔 Remaining ₹85 is due after code delivery.\n\n"
        )
    else:
        summary_text += f"💵 Total: ₹{total}\n\n"
    summary_text += "Select Pay Now to continue."

    bot.send_message(
        chat_id,
        summary_text,
        reply_markup=keyboard
    )


# =========================================================
# FIXED QUANTITY
# =========================================================

@bot.callback_query_handler(
    func=lambda call:
    call.data.startswith("qty_")
)
def fixed_quantity(call):

    # Voucher IDs can contain underscores, for example:
    # rare_rabbit_250. Split only at the LAST underscore
    # so the final part remains the selected quantity.
    try:
        payload = call.data[4:]  # remove "qty_"
        voucher_id, quantity_text = payload.rsplit("_", 1)
        quantity = int(quantity_text)

    except (ValueError, AttributeError):
        bot.answer_callback_query(
            call.id,
            "❌ Invalid quantity.",
            show_alert=True
        )
        return

    if voucher_id not in VOUCHERS:
        bot.answer_callback_query(
            call.id,
            "❌ Invalid voucher.",
            show_alert=True
        )
        return

    if quantity <= 0:
        bot.answer_callback_query(
            call.id,
            "❌ Invalid quantity.",
            show_alert=True
        )
        return

    bot.answer_callback_query(call.id)

    show_order_summary(
        call.message.chat.id,
        call.from_user.id,
        voucher_id,
        quantity
    )


# =========================================================
# CUSTOM QUANTITY
# =========================================================

@bot.callback_query_handler(
    func=lambda call:
    call.data.startswith("other_")
)
def other_amount(call):

    voucher_id = call.data.replace(
        "other_",
        "",
        1
    )

    if voucher_id not in VOUCHERS:

        bot.answer_callback_query(
            call.id,
            "❌ Invalid voucher.",
            show_alert=True
        )

        return

    bot.answer_callback_query(call.id)

    msg = bot.send_message(
        call.message.chat.id,
        "🔢 Quantity enter karein:\n\n"
        "Example: 7"
    )

    bot.register_next_step_handler(
        msg,
        process_custom_quantity,
        voucher_id
    )


def process_custom_quantity(
    message,
    voucher_id
):

    try:

        quantity = int(
            message.text.strip()
        )

        if quantity <= 0:
            raise ValueError

    except (ValueError, AttributeError):

        bot.send_message(
            message.chat.id,
            "❌ Please valid number enter karein."
        )

        return

    show_order_summary(
        message.chat.id,
        message.from_user.id,
        voucher_id,
        quantity
    )


# =========================================================
# CANCEL ORDER
# =========================================================

@bot.callback_query_handler(
    func=lambda call:
    call.data.startswith("cancel_order_")
)
def cancel_order(call):

    try:

        order_id = int(
            call.data.replace(
                "cancel_order_",
                "",
                1
            )
        )

    except ValueError:

        bot.answer_callback_query(
            call.id,
            "❌ Invalid order.",
            show_alert=True
        )

        return

    conn = get_db()
    cursor = conn.cursor()

    cursor.execute("""
        UPDATE orders
        SET status = 'cancelled'
        WHERE id = ?
        AND user_id = ?
        AND status = 'payment_pending'
    """, (
        order_id,
        call.from_user.id
    ))

    changed = cursor.rowcount

    conn.commit()
    conn.close()

    if changed:

        bot.answer_callback_query(
            call.id,
            "Order cancelled."
        )

        bot.send_message(
            call.message.chat.id,
            "❌ Order cancelled."
        )

    else:

        bot.answer_callback_query(
            call.id,
            "❌ Order cannot be cancelled.",
            show_alert=True
        )


# =========================================================
# PAY NOW
# =========================================================

@bot.callback_query_handler(
    func=lambda call:
    call.data.startswith("pay_") and not call.data.startswith("pay_balance_")
)
def pay_now(call):

    try:

        order_id = int(
            call.data.replace(
                "pay_",
                "",
                1
            )
        )

    except ValueError:

        bot.answer_callback_query(
            call.id,
            "❌ Invalid order.",
            show_alert=True
        )

        return

    conn = get_db()
    cursor = conn.cursor()

    cursor.execute("""
        SELECT *
        FROM orders
        WHERE id = ?
        AND user_id = ?
    """, (
        order_id,
        call.from_user.id
    ))

    order = cursor.fetchone()

    conn.close()

    if not order:

        bot.answer_callback_query(
            call.id,
            "❌ Order not found.",
            show_alert=True
        )

        return

    if order["status"] != "payment_pending":

        bot.answer_callback_query(
            call.id,
            "❌ This order is not active.",
            show_alert=True
        )

        return

    # Only new users buying Westside see the Full/Half payment choice
    # after pressing Pay Now in the order summary.
    if order["voucher_id"] == "westside_750" and order["is_new_user_offer"]:
        choice_keyboard = types.InlineKeyboardMarkup(row_width=1)
        choice_keyboard.add(
            types.InlineKeyboardButton(
                "💯 Full Payment (₹170)",
                callback_data=f"newpay_{order_id}_full"
            ),
            types.InlineKeyboardButton(
                "🌓 Half Payment (₹85)",
                callback_data=f"newpay_{order_id}_half"
            )
        )
        bot.answer_callback_query(call.id)
        bot.send_message(
            call.message.chat.id,
            "🆕 NEW USER ONLY — Westside Gift Card ₹750\n\nChoose your payment option:",
            reply_markup=choice_keyboard
        )
        return

    amount_to_pay = order["amount_due"] or order["total"]
    payment_sessions[
        call.from_user.id
    ] = {
        "order_id": order_id,
        "voucher_id": order["voucher_id"],
        "quantity": order["quantity"],
        "total": amount_to_pay,
        "payment_stage": "initial"
    }

    bot.answer_callback_query(call.id)

    try:

        # Telegram inline keyboard URL buttons do NOT support upi:// links.
        # So we generate a dynamic UPI QR containing the exact order amount.
        if qrcode is None:
            bot.send_message(
                call.message.chat.id,
                "❌ Payment QR generator is missing.\n\n"
                "Open the Pydroid terminal and run:\n"
                "pip install qrcode[pil]\n\n"
                "Then restart the bot."
            )
            return

        upi_link = (
            "upi://pay?"
            f"pa={quote(UPI_ID)}&"
            f"pn={quote('Voucher Bot')}&"
            f"am={quote(str(amount_to_pay))}&"
            "cu=INR&"
            f"tn={quote('Order ' + get_order_ref(order_id))}"
        )

        qr = BytesIO()
        qr_img = qrcode.make(upi_link)
        qr_img.save(qr, format="PNG")
        qr.seek(0)
        qr.name = "payment_qr.png"

        bot.send_photo(
            call.message.chat.id,
            qr,
            caption=(
                "💳 UPI PAYMENT\n\n"
                f"🆔 Order ID: {get_order_ref(order_id)}\n"
                f"🎟️ Service: {VOUCHERS[order['voucher_id']]['name']}\n"
                f"📦 Quantity: {order['quantity']}\n"
                f"💰 PAY EXACTLY: ₹{amount_to_pay}\n\n"
                f"📲 UPI ID: `{UPI_ID}`\n\n"
                f"📌 The amount ₹{amount_to_pay} will be pre-filled in the QR.\n\n"
                "After payment, send your UTR, payer name, and screenshot."
            ),
            parse_mode="Markdown"
        )
    except Exception as e:

        bot.send_message(
            call.message.chat.id,
            "❌ The payment QR could not be generated. Please restart the bot and try again."
        )
        print("QR error:", e)
        return

    msg = bot.send_message(
        call.message.chat.id,
        "🔢 **Enter UTR Number**\n\n"
        "After Payment Send Here UTR👇:",
        parse_mode="Markdown"
    )

    bot.register_next_step_handler(
        msg,
        get_utr
    )


# =========================================================
# NEW USER WESTSIDE PAYMENT CHOICE
# =========================================================

@bot.callback_query_handler(func=lambda call: call.data.startswith("newpay_"))
def new_user_payment_choice(call):
    try:
        _, order_id_text, choice = call.data.split("_", 2)
        order_id = int(order_id_text)
    except (ValueError, TypeError):
        bot.answer_callback_query(call.id, "Invalid payment option.", show_alert=True)
        return

    if choice not in ("full", "half"):
        bot.answer_callback_query(call.id, "Invalid payment option.", show_alert=True)
        return

    order = get_order(order_id)
    if (not order or order["user_id"] != call.from_user.id
            or order["status"] != "payment_pending"
            or not order["is_new_user_offer"]
            or order["voucher_id"] != "westside_750"):
        bot.answer_callback_query(call.id, "This offer is not available for this order.", show_alert=True)
        return

    amount = 170 if choice == "full" else 85
    balance = 0 if choice == "full" else 85
    conn = get_db()
    cursor = conn.cursor()
    cursor.execute("""
        UPDATE orders
        SET amount_due = ?, balance_due = ?, payment_choice = ?
        WHERE id = ? AND user_id = ? AND status = 'payment_pending'
    """, (amount, balance, choice, order_id, call.from_user.id))
    conn.commit()
    conn.close()

    payment_sessions[call.from_user.id] = {
        "order_id": order_id, "voucher_id": order["voucher_id"],
        "quantity": order["quantity"], "total": amount,
        "payment_stage": "initial", "payment_choice": choice
    }
    bot.answer_callback_query(call.id)

    if qrcode is None:
        bot.send_message(call.message.chat.id, "❌ Payment QR generator is missing. Install qrcode[pil] in Pydroid and restart the bot.")
        return

    upi_link = (
        "upi://pay?" + f"pa={quote(UPI_ID)}&pn={quote('Voucher Bot')}&"
        f"am={quote(str(amount))}&cu=INR&"
        f"tn={quote('Order ' + get_order_ref(order_id))}"
    )
    qr = BytesIO()
    qrcode.make(upi_link).save(qr, format="PNG")
    qr.seek(0)
    qr.name = "payment_qr.png"

    caption = (
        "💳 UPI PAYMENT\n\n"
        f"🆔 Order ID: {get_order_ref(order_id)}\n"
        f"🎟️ Service: {VOUCHERS[order['voucher_id']]['name']}\n"
        f"📦 Quantity: {order['quantity']}\n"
        f"💰 PAY EXACTLY: ₹{amount}\n\n"
        f"📲 UPI ID: `{UPI_ID}`\n\n"
        f"📌 The amount ₹{amount} will be pre-filled in the QR.\n\n"
        "After payment, send your UTR, payer name, and screenshot."
    )
    if choice == "half":
        caption += "\n\n🔔 After code delivery, remaining ₹85 is due within 24 hours."
    else:
        caption += "\n\n✅ Full payment selected. No balance will remain."

    bot.send_photo(call.message.chat.id, qr, caption=caption,
                   parse_mode="Markdown")

    msg = bot.send_message(
        call.message.chat.id,
        "🔢 **Enter UTR Number**\n\nAfter Payment Send Here UTR👇:",
        parse_mode="Markdown"
    )
    bot.register_next_step_handler(msg, get_utr)


# =========================================================
# GET UTR
# =========================================================

def get_utr(message):

    user_id = message.from_user.id

    if user_id not in payment_sessions:

        bot.send_message(
            message.chat.id,
            "❌ Payment session expired."
        )

        return

    utr = (
        message.text or ""
    ).strip()

    if not utr:

        msg = bot.send_message(
            message.chat.id,
            "❌ UTR cannot be empty. Please send it again:"
        )

        bot.register_next_step_handler(
            msg,
            get_utr
        )

        return

    payment_sessions[
        user_id
    ]["utr"] = utr

    msg = bot.send_message(
        message.chat.id,
        "👤 **Enter Payer Name**\n\n"
        "Send Payer Name:",
        parse_mode="Markdown"
    )

    bot.register_next_step_handler(
        msg,
        get_payer_name
    )


