@bot.callback_query_handler(func=lambda call: call.data.startswith("payment_info_"))
def payment_info(call):
    try:
        order_id = int(call.data.split("_")[-1])
    except ValueError:
        bot.answer_callback_query(call.id, "Invalid order.", show_alert=True)
        return

    order = get_order(order_id)
    if not order or order["user_id"] != call.from_user.id:
        bot.answer_callback_query(call.id, "Order not found.", show_alert=True)
        return

    bot.answer_callback_query(
        call.id,
        f"Pay exactly ₹{(order['balance_due'] if order['status'] == 'partial_delivered' else (order['amount_due'] or order['total']))} by scanning the QR.",
        show_alert=True
    )


def get_payment_screenshot(message):

    user_id = message.from_user.id

    if user_id not in payment_sessions:

        bot.send_message(
            message.chat.id,
            "❌ Payment session expired."
        )

        return

    if not message.photo:

        msg = bot.send_message(
            message.chat.id,
            "❌ Please send the payment screenshot as a photo."
        )

        bot.register_next_step_handler(
            msg,
            get_payment_screenshot
        )

        return

    session = payment_sessions[user_id]

    screenshot_id = (
        message.photo[-1].file_id
    )

    conn = get_db()
    cursor = conn.cursor()

    cursor.execute("""
        UPDATE orders
        SET utr = ?,
            payer_name = ?,
            screenshot_file_id = ?,
            payment_stage = ?,
            status = 'waiting_verification'
        WHERE id = ?
        AND user_id = ?
    """, (
        session["utr"],
        session["payer_name"],
        screenshot_id,
        session.get("payment_stage", "initial"),
        session["order_id"],
        user_id
    ))

    conn.commit()
    conn.close()

    approve_command = (f"/approve_balance {session['order_id']}" if session.get("payment_stage") == "balance" else f"/approve {session['order_id']}")
    admin_text = (
        "🔔 NEW PAYMENT SUBMISSION\n\n"
        f"🆔 Order ID: {get_order_ref(session['order_id'])}\n"
        f"👤 User ID: {user_id}\n"
        f"🎟️ Voucher: "
        f"{VOUCHERS[session['voucher_id']]['name']}\n"
        f"📦 Quantity: {session['quantity']}\n"
        f"💰 Amount: ₹{session['total']}\n"
        f"🧾 Payment Stage: {session.get('payment_stage', 'initial')}\n"
        f"🔢 UTR: {session['utr']}\n"
        f"👤 Payer Name: "
        f"{session['payer_name']}\n\n"
        f"Approve:\n{approve_command}\n\n"
        f"Reject:\n"
        f"/reject {session['order_id']}"
    )

    try:

        bot.send_message(
            ADMIN_ID,
            admin_text
        )

        bot.send_photo(
            ADMIN_ID,
            screenshot_id,
            caption=(
                f"📸 Payment Screenshot\n"
                f"Order {get_order_ref(session['order_id'])}"
            )
        )

    except Exception as e:

        print(
            "Admin notification error:",
            e
        )

    bot.send_message(
        message.chat.id,
        "✅ Payment Details Received!\n\n"
        f"🆔 Order ID: {get_order_ref(session['order_id'])}\n"
        "⏳ Payment Verification Under Review.\n\n"
        "After Payment Verified Voucher Will  "
        "Automatically Delivered."
    )

    del payment_sessions[user_id]


