# PAYMENT REMINDER / OUTSTANDING BALANCE
# =========================================================

@bot.message_handler(func=lambda message: message.text == "⏰ Payment Reminder")
def payment_reminder_status(message):
    save_user(message)

    conn = get_db()
    cursor = conn.cursor()
    cursor.execute("""
        SELECT id, voucher_id, balance_due, status, payment_stage
        FROM orders
        WHERE user_id = ?
          AND (
              (status = 'partial_delivered' AND balance_due > 0)
              OR (status = 'waiting_verification' AND payment_stage = 'balance')
          )
        ORDER BY id DESC
    """, (message.from_user.id,))
    pending_orders = cursor.fetchall()
    conn.close()

    if not pending_orders:
        bot.send_message(
            message.chat.id,
            "✅ You have no pending balance payments.\n\nAll your payments are up to date.",
            reply_markup=main_menu(message.from_user.id)
        )
        return

    bot.send_message(
        message.chat.id,
        "⏰ PAYMENT REMINDER\n\nHere are your pending payment details:"
    )

    for order in pending_orders:
        order_ref = get_order_ref(order["id"])
        voucher_name = VOUCHERS.get(order["voucher_id"], {}).get("name", order["voucher_id"])

        if order["status"] == "waiting_verification" and order["payment_stage"] == "balance":
            bot.send_message(
                message.chat.id,
                f"🆔 Order ID: {order_ref}\n"
                f"🎟️ Voucher: {voucher_name}\n"
                f"💰 Balance submitted: ₹{order['balance_due']}\n\n"
                "⏳ Your balance payment is under verification. Please wait for confirmation."
            )
            continue

        keyboard = types.InlineKeyboardMarkup()
        keyboard.add(types.InlineKeyboardButton(
            f"💳 Pay Now • ₹{order['balance_due']}",
            callback_data=f"pay_balance_{order['id']}"
        ))
        bot.send_message(
            message.chat.id,
            f"🆔 Order ID: {order_ref}\n"
            f"🎟️ Voucher: {voucher_name}\n"
            f"💰 Remaining Payment: ₹{order['balance_due']}\n\n"
            "Press the button below to pay your remaining balance.",
            reply_markup=keyboard
        )


# =========================================================
# ORDER HISTORY / PURCHASE LEDGER
# =========================================================

@bot.message_handler(
    func=lambda message:
    message.text == "🏷️My Order"
)
def my_orders(message):
    save_user(message)

    conn = get_db()
    cursor = conn.cursor()

    cursor.execute("""
        SELECT id, order_ref, voucher_id, quantity, total, status, created_at
        FROM orders
        WHERE user_id = ?
        ORDER BY id DESC
        LIMIT 50
    """, (message.from_user.id,))
    orders = cursor.fetchall()
    conn.close()

    if not orders:
        bot.send_message(
            message.chat.id,
            "📦 <b>MY ORDERS</b>\n\n"
            "You Have Not Bought Any Item From Our Bot.",
            parse_mode="HTML"
        )
        return

    # My Order intentionally shows NO voucher codes.
    # Codes can only be obtained through Recover Codes using the Order ID.
    blocks = ["📦 <b>MY ORDERS</b>", "━━━━━━━━━━━━━━━━━━"]

    for order in orders:
        voucher = VOUCHERS.get(order["voucher_id"], {})
        voucher_name = voucher.get("name", order["voucher_id"])
        order_ref = order["order_ref"] or get_order_ref(order["id"])

        block = (
            f"🎟️ <b>VOUCHER:</b> {voucher_name}\n"
            f"📦 <b>QTY:</b> {order['quantity']}\n"
            f"💰 <b>AMOUNT:</b> ₹{order['total']}\n"
            f"🆔 <b>ORDER ID:</b> <code>{order_ref}</code>\n"
        )

        if order["status"] == "completed":
            block += "✅ <b>STATUS:</b> Completed\n"
            block += "🔑 <i>Use Recover Codes and enter this Order ID to get your voucher code.</i>\n"
        elif order["status"] == "waiting_verification":
            block += "⏳ <b>STATUS:</b> Payment verification pending\n"
        elif order["status"] == "payment_pending":
            block += "💳 <b>STATUS:</b> Payment pending\n"
        elif order["status"] == "rejected":
            block += "❌ <b>STATUS:</b> Order rejected\n"
        elif order["status"] == "cancelled":
            block += "❌ <b>STATUS:</b> Order cancelled\n"
        else:
            block += f"📌 <b>STATUS:</b> {order['status']}\n"

        block += f"📅 <b>DATE:</b> {order['created_at']}"
        blocks.append(block)
        blocks.append("━━━━━━━━━━━━━━━━━━")

    current = ""
    for block in blocks:
        candidate = block if not current else current + "\n" + block
        if len(candidate) > 3900:
            bot.send_message(message.chat.id, current, parse_mode="HTML")
            current = block
        else:
            current = candidate

    if current:
        bot.send_message(message.chat.id, current, parse_mode="HTML")


