def recover_by_order_id(message):
    raw_text = (message.text or "").strip()

    # /cancel returns the user to the main menu while recovering a code.
    if raw_text.lower() == "/cancel":
        bot.send_message(
            message.chat.id,
            "↩️ Back to main menu.",
            reply_markup=main_menu(message.from_user.id)
        )
        return

    order_ref = raw_text.upper()

    if not order_ref:
        msg = bot.send_message(
            message.chat.id,
            "❌ Order ID Does Not Be Empty.\n"
            "Check & Send Again Order ID"
        )
        bot.register_next_step_handler(msg, recover_by_order_id)
        return

    conn = get_db()
    cursor = conn.cursor()

    # User can recover only their own completed order.
    cursor.execute("""
        SELECT
            orders.id AS order_id,
            orders.voucher_id,
            orders.quantity,
            orders.created_at,
            voucher_codes.code
        FROM orders
        JOIN voucher_codes
            ON voucher_codes.order_id = orders.id
        WHERE UPPER(TRIM(orders.order_ref)) = ?
          AND orders.user_id = ?
          AND orders.status = 'completed'
          AND voucher_codes.status = 'assigned'
        ORDER BY voucher_codes.id ASC
    """, (order_ref, message.from_user.id))

    rows = cursor.fetchall()
    conn.close()

    if not rows:
        bot.send_message(
            message.chat.id,
            "❌ No verified voucher code was found with this Order ID..\n\n"
            "Check your order ID. Only your completed orders can be recovered. "
            
        )
        return

    voucher = VOUCHERS.get(rows[0]["voucher_id"], {})

    text = (
        "✅ Code Recovery Successful!\n\n"
        f"🆔 Order ID: {get_order_ref(rows[0]['order_id'])}\n"
        f"🎟️ Voucher: {voucher.get('name', rows[0]['voucher_id'])}\n"
        f"📅 {rows[0]['created_at']}\n\n"
        "🔑 Your Voucher Codes:\n\n"
    )

    for index, row in enumerate(rows, 1):
        text += f"{index}. `{row['code']}`\n"

    text += "\n⚠️ Is code ko kisi ke saath share na karein."

    bot.send_message(
        message.chat.id,
        text,
        parse_mode="Markdown"
    )


