@bot.message_handler(commands=["addcode"])
def add_code(message):

    if not is_admin(message.from_user.id):
        return

    parts = message.text.split(maxsplit=2)
    if len(parts) < 3:
        bot.send_message(
            message.chat.id,
            "❌ Format:\n\n/addcode rare_rabbit_250 ABC123XYZ"
        )
        return

    voucher_id = parts[1].strip()
    code = parts[2].strip()

    if voucher_id not in VOUCHERS:
        bot.send_message(
            message.chat.id,
            "❌ Invalid voucher ID.\n\nAvailable:\n"
            + "\n".join(VOUCHERS.keys())
        )
        return

    if not code:
        bot.send_message(message.chat.id, "❌ Voucher code empty hai.")
        return

    conn = get_db()
    cursor = conn.cursor()
    try:
        # Duplicate tabhi maana jayega jab code abhi stock ya assigned records me maujood ho.
        # Admin Panel se stock se nikala gaya code voucher_codes me nahi hota;
        # uski purani history entry hata kar use dobara add karne denge.
        cursor.execute("""
            SELECT code FROM voucher_codes
            WHERE TRIM(code) = ? COLLATE NOCASE LIMIT 1
        """, (code,))

        if cursor.fetchone():
            bot.send_message(
                message.chat.id,
                "⚠️ Duplicate code detected!\n\n"
                "Ye code abhi stock ya assigned records mein maujood hai.\n"
                "Isse dobara add nahi kiya gaya.\n\n"
                f"🔑 `{code}`",
                parse_mode="Markdown"
            )
            return

        # Purani history-only entry stale hai (code stock se remove ho chuka tha).
        cursor.execute("""
            DELETE FROM voucher_code_history
            WHERE TRIM(code) = ? COLLATE NOCASE
        """, (code,))
        cursor.execute("""
            INSERT INTO voucher_code_history (code, voucher_id)
            VALUES (?, ?)
        """, (code, voucher_id))
        cursor.execute("""
            INSERT INTO voucher_codes (voucher_id, code)
            VALUES (?, ?)
        """, (voucher_id, code))
        conn.commit()

        bot.send_message(
            message.chat.id,
            "✅ Voucher code added!\n\n"
            f"🎟️ {VOUCHERS[voucher_id]['name']}\n"
            f"🔑 `{code}`",
            parse_mode="Markdown"
        )
    except sqlite3.IntegrityError:
        conn.rollback()
        bot.send_message(
            message.chat.id,
            "⚠️ Duplicate code detected! Ye code pehle add ho chuka hai.\n"
            "Dobara add nahi kiya gaya."
        )
    finally:
        conn.close()


# =========================================================
# ADMIN - ADD MANY CODES
# =========================================================

@bot.message_handler(commands=["addcodes"])
def add_codes(message):

    if not is_admin(message.from_user.id):
        return

    parts = message.text.split(maxsplit=1)
    if len(parts) < 2:
        bot.send_message(
            message.chat.id,
            "❌ Format:\n\n/addcodes rare_rabbit_250\nCODE1\nCODE2\nCODE3"
        )
        return

    lines = parts[1].splitlines()
    voucher_id = lines[0].strip()
    if voucher_id not in VOUCHERS:
        bot.send_message(message.chat.id, "❌ Invalid voucher ID.")
        return

    codes = [line.strip() for line in lines[1:] if line.strip()]
    if not codes:
        bot.send_message(message.chat.id, "❌ Codes nahi mile.")
        return

    conn = get_db()
    cursor = conn.cursor()
    added = 0
    duplicate = 0

    for code in codes:
        try:
            cursor.execute("SAVEPOINT add_one_code")
            cursor.execute("""
                SELECT code FROM voucher_codes
                WHERE TRIM(code) = ? COLLATE NOCASE LIMIT 1
            """, (code,))

            if cursor.fetchone():
                duplicate += 1
                cursor.execute("RELEASE SAVEPOINT add_one_code")
                continue

            # History-only code stock se remove ho chuka hai, isliye re-add allowed hai.
            cursor.execute("""
                DELETE FROM voucher_code_history
                WHERE TRIM(code) = ? COLLATE NOCASE
            """, (code,))
            cursor.execute("""
                INSERT INTO voucher_code_history (code, voucher_id)
                VALUES (?, ?)
            """, (code, voucher_id))
            cursor.execute("""
                INSERT INTO voucher_codes (voucher_id, code)
                VALUES (?, ?)
            """, (voucher_id, code))
            cursor.execute("RELEASE SAVEPOINT add_one_code")
            added += 1
        except sqlite3.IntegrityError:
            cursor.execute("ROLLBACK TO SAVEPOINT add_one_code")
            cursor.execute("RELEASE SAVEPOINT add_one_code")
            duplicate += 1

    conn.commit()
    conn.close()

    bot.send_message(
        message.chat.id,
        "📦 Bulk codes processed!\n\n"
        f"🎟️ {VOUCHERS[voucher_id]['name']}\n"
        f"✅ Added: {added}\n"
        f"⚠️ Duplicate (skipped): {duplicate}"
    )


