# PUBLIC CHANNEL PURCHASE ALERT (MASK USER ID)
# =========================================================

def post_purchase_alert(order, order_id, partial=False):
    """Post a public purchase alert without exposing the buyer's full Telegram ID."""
    try:
        user_id = int(order["user_id"])
        try:
            tg_user = bot.get_chat(user_id)
            display_name = " ".join(
                part for part in [getattr(tg_user, "first_name", ""),
                                  getattr(tg_user, "last_name", "")]
                if part
            ).strip() or "Telegram User"
        except Exception:
            display_name = "Telegram User"

        user_id_text = str(user_id)
        masked_id = user_id_text[:5] + ("*" * max(1, len(user_id_text) - 5))
        voucher_name = VOUCHERS.get(order["voucher_id"], {}).get("name", "Voucher")
        amount = order["total"]

        alert = (
            "🎉 NEW PURCHASE ALERT\\n\\n"
            f"👤 Name: {display_name}\\n"
            f"🆔 User ID: {masked_id}\\n"
            f"🎟 Voucher: {voucher_name}\\n"
            f"📦 Quantity: {order['quantity']}\\n"
            f"💰 Amount: ₹{amount}\\n"
            f"🧾 Order ID: {get_order_ref(order_id)}\\n"
            + ("🟡 Status: Partially Paid / Delivered" if partial
               else "✅ Payment Successful")
        )
        bot.send_message(CHANNEL, alert)
    except Exception as exc:
        print("Channel purchase alert error:", exc)


