@bot.message_handler(commands=["approve"])
def approve_order(message):
    if not is_admin(message.from_user.id):
        return

    parts = message.text.split()
    if len(parts) != 2:
        bot.send_message(message.chat.id, "Format: /approve ORDER_ID")
        return
    try:
        order_id = int(parts[1])
    except ValueError:
        bot.send_message(message.chat.id, "Invalid order ID.")
        return

    conn = get_db()
    cursor = conn.cursor()
    cursor.execute("SELECT * FROM orders WHERE id = ?", (order_id,))
    order = cursor.fetchone()
    if not order:
        conn.close()
        bot.send_message(message.chat.id, "Order not found.")
        return
    if order["status"] != "waiting_verification" or order["payment_stage"] != "initial":
        conn.close()
        bot.send_message(message.chat.id, f"Order status: {order['status']} / {order['payment_stage']}")
        return

    cursor.execute("""
        SELECT id, code FROM voucher_codes
        WHERE voucher_id = ? AND status = 'available'
        ORDER BY id ASC LIMIT ?
    """, (order["voucher_id"], order["quantity"]))
    codes = cursor.fetchall()
    if len(codes) < order["quantity"]:
        conn.close()
        bot.send_message(message.chat.id, f"Insufficient stock. Required: {order['quantity']}; available: {len(codes)}")
        return

    assigned_codes = []
    for item in codes:
        cursor.execute("""
            UPDATE voucher_codes
            SET assigned_to = ?, order_id = ?, status = 'assigned'
            WHERE id = ? AND status = 'available'
        """, (order["user_id"], order_id, item["id"]))
        assigned_codes.append(item["code"])

    is_split_offer = bool(order["is_new_user_offer"]) and order["payment_choice"] == "half"
    if is_split_offer:
        due_at = (datetime.now() + timedelta(hours=24)).strftime("%Y-%m-%d %H:%M:%S")
        cursor.execute("""
            UPDATE orders
            SET status = 'partial_delivered', amount_paid = 85,
                balance_due = 85, reminder_at = ?, reminder_sent = 0
            WHERE id = ?
        """, (due_at, order_id))
    else:
        cursor.execute("""
            UPDATE orders
            SET status = 'completed', amount_paid = total,
                balance_due = 0, reminder_sent = 1
            WHERE id = ?
        """, (order_id,))

    conn.commit()
    conn.close()

    code_text = (
        "🎉 PAYMENT VERIFIED!\n\n"
        f"🆔 Order ID: {get_order_ref(order_id)}\n"
        f"🎟️ {VOUCHERS[order['voucher_id']]['name']}\n"
        f"📦 Quantity: {order['quantity']}\n\n"
        "🔑 Your Voucher Code(s):\n\n"
    )
    for index, code in enumerate(assigned_codes, 1):
        code_text += f"{index}. `{code}`\n"
    code_text += "\nYou can view your codes anytime using Recover Codes."

    # Public channel gets a masked-ID purchase alert; full ID remains admin-only.
    post_purchase_alert(order, order_id, partial=is_split_offer)

    if is_split_offer:
        balance_keyboard = types.InlineKeyboardMarkup()
        balance_keyboard.add(types.InlineKeyboardButton(
            "💳 Pay Remaining ₹85", callback_data=f"pay_balance_{order_id}"
        ))
        code_text += "\n\nRemaining Balance: ₹85\nPlease complete the remaining payment within 24 hours."
        bot.send_message(order["user_id"], code_text, parse_mode="Markdown", reply_markup=balance_keyboard)
        bot.send_message(message.chat.id, f"Order #{order_id}: first ₹85 verified; code delivered. ₹85 balance reminder scheduled in 24 hours.")
    else:
        bot.send_message(order["user_id"], code_text, parse_mode="Markdown")
        bot.send_message(message.chat.id, f"Order #{order_id} approved. {len(assigned_codes)} code(s) delivered.")


