@bot.callback_query_handler(func=lambda call: call.data.startswith("pay_balance_"))
def pay_balance(call):
    try:
        order_id = int(call.data.rsplit("_", 1)[1])
    except ValueError:
        bot.answer_callback_query(call.id, "Invalid order.", show_alert=True)
        return

    order = get_order(order_id)
    if not order or order["user_id"] != call.from_user.id or order["status"] != "partial_delivered" or order["balance_due"] <= 0:
        bot.answer_callback_query(call.id, "No pending balance found.", show_alert=True)
        return

    amount = order["balance_due"]
    payment_sessions[call.from_user.id] = {
        "order_id": order_id,
        "voucher_id": order["voucher_id"],
        "quantity": order["quantity"],
        "total": amount,
        "payment_stage": "balance"
    }
    bot.answer_callback_query(call.id)

    if qrcode is None:
        bot.send_message(call.message.chat.id, "Payment QR generator is unavailable. Install qrcode[pil] in Pydroid and restart the bot.")
        return
    upi_link = (
        "upi://pay?" + f"pa={quote(UPI_ID)}&pn={quote('Voucher Bot')}&"
        f"am={quote(str(amount))}&cu=INR&tn={quote('Balance ' + get_order_ref(order_id))}"
    )
    qr = BytesIO()
    qrcode.make(upi_link).save(qr, format="PNG")
    qr.seek(0)
    qr.name = "balance_payment_qr.png"
    bot.send_photo(
        call.message.chat.id, qr,
        caption=(f"💳 BALANCE PAYMENT\n\nOrder ID: {get_order_ref(order_id)}\n"
                 f"Voucher: {VOUCHERS[order['voucher_id']]['name']}\n"
                 f"PAY EXACTLY: ₹{amount}\nUPI ID: `{UPI_ID}`\n\n"
                 "After payment, send your UTR, payer name, and screenshot."),
        parse_mode="Markdown"
    )
    msg = bot.send_message(call.message.chat.id, "Enter the UTR number for your balance payment:")
    bot.register_next_step_handler(msg, get_utr)


def send_due_balance_reminders():
    while True:
        try:
            now_text = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            conn = get_db()
            cursor = conn.cursor()
            cursor.execute("""
                SELECT id, user_id, balance_due FROM orders
                WHERE status = 'partial_delivered'
                  AND balance_due > 0
                  AND reminder_sent = 0
                  AND reminder_at IS NOT NULL
                  AND reminder_at <= ?
            """, (now_text,))
            due_orders = cursor.fetchall()
            for row in due_orders:
                keyboard = types.InlineKeyboardMarkup()
                keyboard.add(types.InlineKeyboardButton(
                    f"💳 Pay Remaining ₹{row['balance_due']}",
                    callback_data=f"pay_balance_{row['id']}"
                ))
                try:
                    bot.send_message(
                        row["user_id"],
                        f"⏰ Payment Reminder\n\nYour Westside Gift Card order {get_order_ref(row['id'])} has an unpaid balance of ₹{row['balance_due']}. Please complete the payment.",
                        reply_markup=keyboard
                    )
                    cursor.execute("UPDATE orders SET reminder_sent = 1 WHERE id = ? AND balance_due > 0", (row["id"],))
                except Exception as send_error:
                    print("Balance reminder error:", send_error)
            conn.commit()
            conn.close()
        except Exception as worker_error:
            print("Reminder worker error:", worker_error)
        time.sleep(60)


