@bot.message_handler(commands=["reject"])
def reject_order(message):

    if not is_admin(
        message.from_user.id
    ):
        return

    parts = message.text.split()

    if len(parts) != 2:

        bot.send_message(
            message.chat.id,
            "❌ Format:\n\n"
            "/reject ORDER_ID"
        )

        return

    try:

        order_id = int(parts[1])

    except ValueError:

        bot.send_message(
            message.chat.id,
            "❌ Invalid order ID."
        )

        return

    conn = get_db()
    cursor = conn.cursor()

    cursor.execute("""
        SELECT user_id, status
        FROM orders
        WHERE id = ?
    """, (order_id,))

    order = cursor.fetchone()

    if not order:

        conn.close()

        bot.send_message(
            message.chat.id,
            "❌ Order not found."
        )

        return

    if order["status"] != "waiting_verification":

        conn.close()

        bot.send_message(
            message.chat.id,
            f"❌ Order status: "
            f"{order['status']}"
        )

        return

    cursor.execute("""
        UPDATE orders
        SET status = CASE WHEN payment_stage = 'balance' THEN 'partial_delivered' ELSE 'rejected' END
        WHERE id = ?
    """, (order_id,))

    conn.commit()
    conn.close()

    bot.send_message(
        order["user_id"],
        f"❌ Payment submission for Order #{order_id} was rejected.\n\n"
        "Please check the payment details and try again. If this is a balance payment, use the Pay Remaining button on your order message."
    )

    bot.send_message(
        message.chat.id,
        f"✅ Order #{order_id} rejected."
    )


