# =========================================================

@bot.message_handler(
    func=lambda message:
    message.from_user.id in broadcast_mode
)
def broadcast_message(message):

    if not is_admin(
        message.from_user.id
    ):
        return

    if (
        message.text
        and message.text.startswith("/")
    ):
        return

    broadcast_mode.discard(
        message.from_user.id
    )

    conn = get_db()
    cursor = conn.cursor()

    cursor.execute("""
        SELECT user_id
        FROM users
    """)

    users = cursor.fetchall()

    conn.close()

    sent = 0
    failed = 0

    for user in users:

        try:

            bot.copy_message(
                chat_id=user["user_id"],
                from_chat_id=message.chat.id,
                message_id=message.message_id
            )

            sent += 1

        except Exception:

            failed += 1

    bot.send_message(
        message.chat.id,
        "📢 Broadcast Complete!\n\n"
        f"✅ Sent: {sent}\n"
        f"❌ Failed: {failed}"
    )


