@bot.callback_query_handler(func=lambda call: call.data.startswith("admin_"))
def admin_panel_actions(call):
    if not is_admin(call.from_user.id):
        bot.answer_callback_query(call.id, "❌ Admin only.", show_alert=True)
        return

    action = call.data
    bot.answer_callback_query(call.id)

    if action == "admin_getcode":
        kb = types.InlineKeyboardMarkup(row_width=1)
        for vid, info in VOUCHERS.items():
            kb.add(types.InlineKeyboardButton(
                f"📤 {info['name']} — Code Nikaalo",
                callback_data=f"getcode_{vid}"
            ))
        bot.send_message(
            call.message.chat.id,
            "📤 Code Nikalne\n\nVoucher select karo. Available stock se 1 code nikala jayega.",
            reply_markup=kb
        )

    elif action == "admin_stock":
        bot.send_message(call.message.chat.id, "📊 /stock")

    elif action == "admin_addcode":
        bot.send_message(call.message.chat.id, "➕ /addcode rare_rabbit_250 CODE")

    elif action == "admin_addcodes":
        bot.send_message(call.message.chat.id, "📦 /addcodes rare_rabbit_250\\nCODE1\\nCODE2\\nCODE3")

    elif action == "admin_order":
        bot.send_message(call.message.chat.id, "🔎 /order ORDER_ID")

    elif action == "admin_broadcast":
        bot.send_message(call.message.chat.id, "📢 /broadcast")


@bot.callback_query_handler(func=lambda call: call.data.startswith("getcode_"))
def admin_getcode_voucher(call):
    if not is_admin(call.from_user.id):
        bot.answer_callback_query(call.id, "❌ Admin only.", show_alert=True)
        return

    voucher_id = call.data[len("getcode_"):]
    if voucher_id not in VOUCHERS:
        bot.answer_callback_query(call.id, "❌ Invalid voucher.", show_alert=True)
        return

    conn = get_db()
    cursor = conn.cursor()
    cursor.execute("""
        SELECT id, code FROM voucher_codes
        WHERE voucher_id = ? AND status = 'available'
        ORDER BY id ASC LIMIT 1
    """, (voucher_id,))
    row = cursor.fetchone()

    if not row:
        conn.close()
        bot.answer_callback_query(call.id, "❌ Stock empty.", show_alert=True)
        return

    cursor.execute(
        "DELETE FROM voucher_codes WHERE id = ? AND status = 'available'",
        (row["id"],)
    )
    conn.commit()
    conn.close()

    bot.answer_callback_query(call.id, "✅ Code nikaal diya gaya.")
    bot.send_message(
        call.message.chat.id,
        f"✅ Code stock se nikaal diya gaya\\n\\n"
        f"🎟️ {VOUCHERS[voucher_id]['name']}\\n"
        f"🔑 `{row['code']}`\\n\\n"
        "Ye code history me save rahega; dobara add nahi ho sakta.",
        parse_mode="Markdown"
    )

